style.css:
@-moz-document domain("desmos.com") {
body, .dcg-container {
    background-color: #0a1f44 !important;
    color: #ffffff !important;
  }
  
  .dcg-calculator-api-container,
  .dcg-expressionlist,
  .dcg-expression-container,
  .dcg-basic-expression,
  .dcg-exppanel,
  .dcg-mq-editable-field {
    background-color: #142850 !important;
    color: #ffffff !important;
  }
  
  .dcg-btn, .dcg-icon-btn, .dcg-mq-editable-field {
    background-color: #1a2f5c !important;
    color: #ffffff !important;
    border-color: #2b4b8a !important;
  }
  
  .dcg-mq-cursor {
    border-left-color: #00aaff !important;
  }
  
  .dcg-tooltip,
  .dcg-tooltip-inner,
  .dcg-tooltip-arrow {
    background-color: #1a2f5c !important;
    color: #ffffff !important;
  }
  
  .dcg-exppanel,
  .dcg-settings-menu,
  .dcg-options-menu,
  .dcg-graphpaper {
    background-color: #0f1d3d !important;
    color: #ffffff !important;
  }
  
  /* links and accents */
  a, .dcg-btn-blue, .dcg-expressionlist .dcg-expressionlist-header,
  .dcg-toggle-switch {
    color: #00aaff !important;
  }
  
  /* expression labels */
  .dcg-exppanel-label-container,
  .dcg-exppanel-label {
    color: #ffffff !important;
  }
  
  /* graph axis and grid lines */
  .dcg-axis-tick, .dcg-grid-line {
    stroke: #5a75b5 !important;
  }
}
